do {
    System.out.println(n);
    n = n + 10;
} while(n < 10);

int count = 0;
for(int i = 0; i < 3; i++) {
    for(int j = 0; j < 4; j++) {
        if(j == 2) {
            break;
        }
        count++;
    }
}
System.out.println(count);

