int total = 0;
for(int i = 1; i <= 4; i++) {
    for(int j = 1; j <= i; j++) {
        total += j;
    }
}
System.out.println(total);

int sum = 0;
for(int i = 1; i <= 6; i++) {
    if(i % 2 == 0) {
        continue;
    }
    sum += i;
}
System.out.println(sum);

int a = 0;
for(int i = 0, j = 10; i < j; i++, j--) {
    a++;
}
System.out.println(a);

int n = 100;
int steps = 0;
while(n > 1) {
    if(n % 2 == 0) {
        n = n / 2;
    } else {
        n = 3 * n + 1;
    }
    steps++;
}
System.out.println(steps);
